import{_ as l,o as t,c as a,a3 as e}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"技术手册写作与审查规则","description":"","frontmatter":{},"headers":[],"relativePath":"AGENTS.md","filePath":"AGENTS.md","lastUpdated":1785382433000}'),s={name:"AGENTS.md"};function d(r,i,n,o,p,h){return t(),a("div",null,[...i[0]||(i[0]=[e(`<h1 id="技术手册写作与审查规则" tabindex="-1">技术手册写作与审查规则 <a class="header-anchor" href="#技术手册写作与审查规则" aria-label="Permalink to &quot;技术手册写作与审查规则&quot;">​</a></h1><p>这些规则适用于在 <code>docs/</code> 下规划、创建、审查或大幅重写 Markdown 技术文章，包括：</p><ul><li><code>docs/frontend/</code>：前端工程手册。</li><li><code>docs/py-agent/</code>：Python Agent 手册。</li><li><code>docs/ts-ai/</code>：TS-AI 全栈手册。</li></ul><p>本文件是通用规则。更深目录中的 <code>AGENTS.md</code> 可以补充特定手册或模块的约束；用户对当前任务的明确要求优先。审查、解释或只要求大纲时不得修改正文。</p><h2 id="课程与模块契约" tabindex="-1">课程与模块契约 <a class="header-anchor" href="#课程与模块契约" aria-label="Permalink to &quot;课程与模块契约&quot;">​</a></h2><p>批量评估或优化一个模块前，先明确课程与模块契约，不能只逐篇润色：</p><ul><li><strong>目标读者</strong>：读者已经掌握什么，允许缺少什么经验。</li><li><strong>毕业能力</strong>：学完后能独立完成哪些可验证任务，而不只是“了解”哪些名词。</li><li><strong>必修主线</strong>：必学、进阶和选修内容分别是什么，推荐顺序是什么。</li><li><strong>模块边界</strong>：本模块接收哪些前置知识，向后续模块交付哪些能力，哪些内容明确不在本模块展开。</li><li><strong>验收产物</strong>：模块结束时应得到什么代码、接口、测试、设计或排障能力。</li><li><strong>贯穿场景</strong>：相邻文章尽量复用稳定的业务场景、术语和数据契约，避免每篇重新发明上下文。</li></ul><p>三本手册共同采用“学习主线 + API 查阅”的双重定位：</p><ul><li>“偏 API 式”适用于 frontend、py-agent 和 ts-ai 的全部技术模块，表示读者既能按依赖顺序系统学习，也能在学完后按对象、职责、概念或 API 家族快速查找。</li><li>目录应直接暴露核心概念、属性、方法、参数或协议，而不是只使用“基础知识”“核心能力”“实战技巧”等无法检索的笼统标题。</li><li>API 应归属于明确的语言、运行时、框架、对象或职责，并解释用途、关键契约、适用边界和失败方式；不能散落在多个偶然出现它的案例中。</li><li>“偏 API 式”不等于把每篇文章都写成完整 API Reference。教程负责建立第一次正确使用的路径，概念文章负责解释模型和机制，API 参考负责系统查找，项目文章负责组合与取舍。</li><li>单篇文章不为追求 API 数量而破坏学习主线。完整覆盖由清晰的模块边界、文章分工和索引共同保证。</li></ul><h3 id="ts-ai-全栈手册附加契约" tabindex="-1">TS-AI 全栈手册附加契约 <a class="header-anchor" href="#ts-ai-全栈手册附加契约" aria-label="Permalink to &quot;TS-AI 全栈手册附加契约&quot;">​</a></h3><ul><li>目标读者具有前端与 TypeScript 基础，可能没有系统学习过 Node.js 服务端、数据库、部署、LLM 或 Agent。</li><li>不得把 NestJS、数据库事务、队列、鉴权、可观测性等后端知识当作默认前置；当前文章不负责讲解时，必须链接到先修文章并说明读者此刻需要掌握到什么程度。</li><li>毕业目标是能够独立设计、实现、测试和部署生产导向的 TypeScript AI 全栈应用，覆盖模型调用、Agent 与工具、服务端、数据与 RAG、记忆与工作流、前端交互、评测、安全、可观测性和部署。</li><li>基础主线只使用完成目标所需的稳定能力；实验性、供应商特有或兼容性敏感能力放入进阶或扩展层，并给出稳定回退。</li><li>模块必须有明确的进入条件和完成标准。单篇文章可以聚焦一个问题，但模块整体不能缺失从输入、实现、调用到验证的完整结果流。</li></ul><h2 id="写作流程" tabindex="-1">写作流程 <a class="header-anchor" href="#写作流程" aria-label="Permalink to &quot;写作流程&quot;">​</a></h2><ul><li>写作前读取对应的路由源、模块与分组索引、目标文章及相邻文章，确认公开路径、学习顺序和内容边界。</li><li>先建立课程或模块契约，再判断单篇文章的主要知识结构；不要从统一模板直接扩写正文。</li><li>先起草并审查 H2/H3 大纲，再展开正文。新文章或大幅重写默认先展示大纲，除非用户明确要求直接生成完整正文。</li><li>明确文章的目标读者、真实前置知识、学习结果、覆盖范围和排除范围，避免与相邻文章重复讲解同一内容。</li><li>用户正在评估大纲或写作质量时，一次只创建或重写一篇文章；模块级评审可以同时覆盖多篇，但评审阶段不修改正文。</li><li>正文完成后重新读取标题树；如果正文已经偏离原定分类轴，应调整大纲或正文，不能保留名不副实的目录。</li><li>只处理当前请求涉及的文件，保留工作区中其他未提交修改。</li></ul><h2 id="大纲信息架构" tabindex="-1">大纲信息架构 <a class="header-anchor" href="#大纲信息架构" aria-label="Permalink to &quot;大纲信息架构&quot;">​</a></h2><ul><li>同级标题只使用一种主要分类轴。不要把概念、API 所有者、运行机制、案例和实施步骤直接混在同一级。</li><li>大纲必须呈现文章的知识地图。读者只看目录，就应该知道主要概念、技巧、属性或 API 有哪些。</li><li>标题保持精简。说明性标题使用中文，API、属性、类名和方法名使用原文并用反引号包裹。</li><li>当“由谁拥有”最有助于理解时，按对象或职责归组 API。例如先区分容器属性与项目属性，不要把它们拆散到多个机制章节。</li><li>基础能力与进阶能力必须分层。兼容性敏感的新能力不能表现得与必学基础具有相同优先级。</li><li>小型示例、调用结果和局部验证应紧跟它们解释的概念或 API；完整案例、综合调试、常见误区和总结通常放在核心知识结构之后。</li><li>不规定固定章节数量，也不强制每篇文章采用机械的“总—分—总”。根据主题选择最清楚的层级。</li><li>理论或 API 文章不使用“先做什么、然后实现、最后上线”等项目交付式标题，但可以提供按学习依赖组织的最小调用路径。</li><li>目录顺序遵循读者的学习依赖，不照搬规范目录、资料检索顺序或源码实现顺序。</li></ul><p>根据文章的实际目的选择大纲类型：</p><table tabindex="0"><thead><tr><th>文章目的</th><th>推荐知识结构</th></tr></thead><tbody><tr><td>API / 属性集合</td><td>基本模型 → 所有者或职责分组 → API 家族 → 签名与数据契约 → 机制与边界 → 示例</td></tr><tr><td>概念 / 原理</td><td>定义 → 组成关系 → 核心机制 → 规则与边界 → 示例与验证</td></tr><tr><td>入门教程</td><td>目标与前置知识 → 最小结果 → 逐步实现 → API 拆解 → 运行验证 → 常见失败</td></tr><tr><td>问题方案</td><td>问题与约束 → 原因 → 候选方案 → 实现 → 验证 → 代价与限制</td></tr><tr><td>故障排查</td><td>症状 → 快速检查 → 诊断路径 → 根因 → 修复 → 回归与预防</td></tr><tr><td>技术决策</td><td>背景与约束 → 候选项 → 对比 → 决策 → 后果 → 复查条件</td></tr><tr><td>项目实践</td><td>需求与验收 → 架构与数据流 → 实现 → 测试 → 交付与验收</td></tr><tr><td>索引 / 清单</td><td>知识地图 → 分类索引 → API 或术语速查 → 学习顺序 → 关联章节</td></tr></tbody></table><p>确认大纲前逐项检查：</p><ul><li>同级标题是否在回答同一种问题。</li><li>核心 API 或技巧是否位于可预测的父级标题下。</li><li>基础内容与进阶内容是否清楚分层。</li><li>章节顺序是否形成可学习的依赖链。</li><li>标题描述的是知识本身，而不是写作动作或空泛结果。</li><li>初学者能否从目录判断学习路径，熟悉后的读者能否从目录快速查找 API。</li><li>文章是否履行模块交给它的职责，同时没有侵入相邻文章的范围。</li></ul><p>新文章或大幅重组文章的大纲审查至少说明：文章类型、主要分类轴、API 或概念归属、基础与进阶分层、内容边界，以及“通过”或“需调整”的结论与具体依据。Markdown 层级合法不能代替语义大纲通过。</p><h2 id="文章分类" tabindex="-1">文章分类 <a class="header-anchor" href="#文章分类" aria-label="Permalink to &quot;文章分类&quot;">​</a></h2><ul><li>规划阶段可以用预期类型指导写作，正文完成后再根据文章的实际目的和组织顺序确定最终分类。</li><li>不一致时调整正文或选择实际匹配的分类，不能只根据标题或路由名称分类。</li><li>新建或大幅重写的正文文章添加以下 frontmatter，字段值以 <code>docs/.vitepress/article-metadata.mjs</code> 为准：</li></ul><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">article</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tutorial</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  structure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tutorial-with-api</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li><code>type</code> 表示文章的主要目的，<code>structure</code> 表示正文实际采用的组织顺序。</li><li>混合文章只保留一个主要类型，结构选择最接近的混合形式，例如 <code>tutorial-with-api</code>。</li><li>首页、分组或模块 <code>index.md</code>、重定向页面不添加文章分类元数据。</li><li>除非当前任务明确要求，不批量补写或重新分类已有文章。</li><li>当前自动检查对 frontend 和 TS-AI 正文强制验证分类元数据；其他目录仍应在新建或大幅重写时人工确认，直到检查脚本覆盖。</li></ul><h2 id="内容与教学要求" tabindex="-1">内容与教学要求 <a class="header-anchor" href="#内容与教学要求" aria-label="Permalink to &quot;内容与教学要求&quot;">​</a></h2><ul><li>新术语必须在首次依赖它之前定义。目标读者可能缺少的语言、后端或 AI 前置知识，要么在当前文章补齐最小必要部分，要么链接到明确的先修文章。</li><li>教程必须给出可运行或可直接验证的结果，包括环境与入口、实现、调用、预期行为和常见失败；不得使用未定义的模型、工具、存储或伪结果。</li><li>文字、代码、输入和输出必须解释同一条结果流。随机生成内容只能说明可验证的结构或约束，不能把某段自然语言输出写成固定保证。</li><li>理论型核心知识优先使用概念关系、属性/API 表格和小型聚焦示例，不写成项目实施日志，也不为显得完整而堆积名词。</li><li>模板必须同时展示填写后的示例，不能只给空模板。</li><li>涉及真实服务时说明必要环境变量、权限和替代测试方式，不得展示真实密钥。</li></ul><p>API 解释深度按文章目的确定：</p><table tabindex="0"><thead><tr><th>文章类型</th><th>必须解释的 API 内容</th></tr></thead><tbody><tr><td>概念 / 原理</td><td>API 所属层次、承担的职责、关键输入输出和理解边界所需的行为</td></tr><tr><td>入门教程</td><td>主路径使用的导入与调用、重要参数、返回结构、异步失败和常见错误</td></tr><tr><td>API 参考</td><td>导入、完整签名或主要重载、参数、返回值、异步拒绝或异常、取消、版本与兼容性边界</td></tr><tr><td>问题方案 / 项目实践</td><td>支撑当前方案的关键 API 和选择理由；通用细节链接到对应 API 文章</td></tr></tbody></table><p>不得为了满足表格而重复解释同一个 API。教程负责第一次正确使用，API 参考负责系统查找，项目文章负责组合与取舍。</p><h2 id="技术依据与版本治理" tabindex="-1">技术依据与版本治理 <a class="header-anchor" href="#技术依据与版本治理" aria-label="Permalink to &quot;技术依据与版本治理&quot;">​</a></h2><ul><li>API、协议和兼容性描述必须以官方文档、正式规范或项目源码中的公开契约为主要依据；第三方文章只能补充理解，不能作为唯一证据。</li><li>每篇版本敏感文章必须能追溯到验证基线。基线可以集中记录在模块版本页，也可以写入正文，但至少包括相关包或 API 版本、供应商或运行环境，以及最后验证日期。</li><li>区分 TypeScript 语言、Node.js 运行时、框架封装、模型供应商 API 和具体模型能力，不能把某一层提供的行为归到另一层。</li><li>供应商特有、实验性、弃用或兼容性敏感的能力必须明确标注。它影响主线时提供稳定回退；不影响主线时放入进阶内容。</li><li>对官方未承诺但实测存在的行为，要标明观察环境和日期，不能写成跨版本保证。</li><li>错误说明应使用实际语义：同步调用说明抛出的异常，异步调用说明 Promise 拒绝、错误对象和可重试条件，不能笼统写成“会报错”。</li><li>关键示例应实际运行，或使用官方类型、测试替身和可重复输入直接验证。无法运行时必须明确未验证的范围，不能声称技术复核通过。</li></ul><h2 id="验证与验收" tabindex="-1">验证与验收 <a class="header-anchor" href="#验证与验收" aria-label="Permalink to &quot;验证与验收&quot;">​</a></h2><p>文章验收分为三层，三者不能互相替代：</p><ol><li><strong>语义大纲审查</strong>：检查文章类型、分类轴、API 归属、学习依赖、基础与进阶分层，以及相邻文章边界。</li><li><strong>技术与教学复核</strong>：按官方依据核对 API 和版本，验证关键示例，并从目标读者视角检查术语、前置知识、结果流、失败边界和完成标准。</li><li><strong>静态与构建检查</strong>：发现可机械判断的元数据、链接、Markdown 渲染和站点构建问题。</li></ol><p>人工检查以下内容：</p><ul><li>frontmatter 标题、H1 和路由标题语义一致。</li><li>标题层级、重复章节、代码围栏、占位符和正文内引用没有明显问题。</li><li>渲染后的目录仍能同时支持学习和 API 查找。</li><li>代码中的导入、类型、调用和预期结果与文章声明的版本基线一致。</li></ul><p>运行项目检查：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pnpm docs:check</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>以检查脚本的实际输出为准。当前脚本主要检查路由页面存在性、Markdown 渲染、站内链接和文章分类元数据；它通过不代表语义大纲、技术正确性或教学质量已经通过。</p><p>创建或大幅重写文章后运行完整构建：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pnpm docs:build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>最终汇报分别列出语义大纲、技术与教学复核、静态检查和构建结果。某一层没有完成时，明确说明未验证范围，不得用“检查通过”笼统概括整篇文章质量。</p>`,42)])])}const b=l(s,[["render",d]]);export{u as __pageData,b as default};
